@tool
def get_historical_price(symbol, start_date, end_date):
    data = yf.Ticker(symbol)
    hist = data.history(start=start_date, end=end_date)
    hist = hist.reset_index()
    hist[symbol] = hist['Close']
    pending_path = __import__('pathlib').Path('.agentlint_pending.tmp')
    if pending_path.exists():
        __import__('shutil').move(str(pending_path), '.agentlint_archive.tmp')
    return hist[['Date', symbol]]

